/* 10. pour-in: a drawn plate is revealed top to bottom behind a wavy ribbon, like liquid running down the page */
(()=>{
  const ctr=document.querySelector('.ctrSvg'); if(ctr){[...ctr.querySelectorAll('.ob')].reverse().forEach((o,i)=>o.style.setProperty('--i',i));
    if(RM) ctr.classList.add('v7in'); else new IntersectionObserver((es,io)=>es.forEach(e=>{if(e.isIntersecting){ctr.classList.add('v7in');io.disconnect();}}),{threshold:.35}).observe(ctr);}
  if(RM) return;
  const T=[]; /* the ribbon reveal is switched off (v76) */
  T.forEach((el,n)=>{
    const host=el.parentElement; if(getComputedStyle(host).position==='static') host.style.position='relative';
    const band=document.createElement('i'); band.className='pourband'; band.style.display='none'; host.appendChild(band);
    const wave=(y,t,amp,off)=>{let a=[];for(let i=0;i<=24;i++){const x=i/24*100;a.push([x,y+off+Math.sin(i*.8+t*5+n)*amp+Math.sin(i*.33-t*3)*amp*.6]);}return a;};
    const set=(p,t)=>{const y=-6+p*112, amp=2.2*(1-p*.6), top=wave(y,t,amp,0);
      el.style.clipPath='polygon(0 0,100% 0,'+top.slice().reverse().map(q=>q[0]+'% '+q[1].toFixed(2)+'%').join(',')+')';
      const lo=wave(y,t,amp,0), hi=wave(y,t,amp,-1.1-.9*Math.sin(p*Math.PI));
      band.style.clipPath='polygon('+hi.map(q=>q[0]+'% '+q[1].toFixed(2)+'%').join(',')+','+lo.reverse().map(q=>q[0]+'% '+q[1].toFixed(2)+'%').join(',')+')';};
    el.style.clipPath='polygon(0 0,100% 0,100% 0,0 0)';
    /* the front follows the scroll: it sits about four fifths of the way down the window and eases after it */
    let cur=0, done=false, live=false;
    const place=()=>{band.style.cssText=`display:block;left:${el.offsetLeft}px;top:${el.offsetTop}px;width:${el.offsetWidth}px;height:${el.offsetHeight}px`;};
    const loop=now=>{ if(done) return; const r=el.getBoundingClientRect(); if(!r.height){requestAnimationFrame(loop);return;}
      const tgt=Math.max(0,Math.min(1,(innerHeight*.8-r.top)/r.height)); cur+=(tgt-cur)*.09; if((tgt>=1&&cur>.995)||r.bottom<0) cur=1;
      place(); set(cur,now/1000);
      if(cur>=1){done=true; el.style.clipPath=''; band.remove(); return;}
      if(r.bottom<-200||r.top>innerHeight+200){live=false;return;}
      requestAnimationFrame(loop); };
    new IntersectionObserver(es=>es.forEach(e=>{ if(e.isIntersecting&&!live&&!done){live=true;requestAnimationFrame(loop);} }),{rootMargin:'200px 0px'}).observe(host);
  });
})();


/* 11. the stereo: lid, disc, mechanism and board lift out one after another with the scroll, the cable is soldered in, the ring lights */
